create or replace function private.record_event(eid uuid,etype text,target uuid,session_id uuid,ip_hash text,consented boolean,segment uuid default null,region text default '') returns jsonb language plpgsql security definer set search_path='' as $$declare sid uuid;entity text;seg uuid;state text;begin
 perform private.service_guard();if not consented then return '{"ignorado":true}';end if;
 if eid is null or session_id is null or length(coalesce(ip_hash,''))<>64 then raise exception 'Evento inválido';end if;
 if etype not in ('visualizacao_perfil','clique_whatsapp','clique_telefone','clique_site','clique_instagram','orcamento_enviado','visualizacao_materia','tempo_materia','clique_perfil_materia','busca') then raise exception 'Evento inválido';end if;
 if etype='busca' then entity:='portal';target:='00000000-0000-4000-8000-000000000000';seg:=segment;state:=nullif(upper(region),'');if seg is not null and not exists(select 1 from public.segmentos where id=seg and ativo) then return '{"ignorado":true}';end if;
 elsif etype in ('visualizacao_materia','tempo_materia','clique_perfil_materia') then entity:='materia';select fornecedor_id into sid from public.materias m where m.id=target and private.article_visible(m);if not found then return '{"ignorado":true}';end if;
 else entity:='fornecedor';sid:=target;if not private.is_supplier_public(sid) then return '{"ignorado":true}';end if;end if;
 if sid is not null then select segmento_id into seg from public.fornecedor_segmentos where fornecedor_id=sid and deletado_em is null order by segmento_id limit 1;select c.uf into state from public.fornecedores f left join public.cidades c on c.id=f.cidade_id where f.id=sid;end if;
 perform pg_advisory_xact_lock(hashtextextended(eid::text,901));if exists(select 1 from public.eventos where id=eid) then return '{"duplicado":true}';end if;
 perform pg_advisory_xact_lock(hashtextextended(ip_hash,902));if (select count(*) from private.analytics_limits l where l.ip_hash=record_event.ip_hash and criado_em>now()-interval '1 hour')>=300 then raise exception 'LIMITE_HORA';end if;
 insert into public.eventos(id,tipo,entidade,entidade_id,fornecedor_id,segmento_id,uf,sessao_anonima) values(eid,etype,entity,target,sid,seg,state,session_id);insert into private.analytics_limits(ip_hash) values(ip_hash);return '{"registrado":true}';end;$$;

create function private.editorial_report(sid uuid,date_from date,date_to date,page_number int) returns jsonb language plpgsql stable security definer set search_path='' as $$begin
 if not private.is_active() or not (private.has_role(auth.uid(),'admin') or private.has_role(auth.uid(),'editor') or (sid is not null and private.can_edit_supplier(sid))) then raise exception 'Acesso negado';end if;
 if date_from is null or date_to is null or date_to<date_from or date_to-date_from>365 or page_number not between 1 and 10000 then raise exception 'Período inválido';end if;
 return jsonb_build_object('items',coalesce((select jsonb_agg(x) from(select m.id,m.titulo,coalesce(sum(d.quantidade)filter(where d.tipo_evento='visualizacao_materia'),0) leituras,coalesce(sum(d.quantidade)filter(where d.tipo_evento='clique_perfil_materia'),0) cliques_perfil,round(coalesce(sum(d.quantidade)filter(where d.tipo_evento='tempo_materia'),0)*30.0/greatest(coalesce(sum(d.quantidade)filter(where d.tipo_evento='visualizacao_materia'),0),1),1) tempo_medio_segundos from public.materias m left join public.metricas_diarias d on d.entidade='materia' and d.entidade_id=m.id and d.data between date_from and date_to where sid is null or m.fornecedor_id=sid group by m.id order by m.criado_em desc,m.id limit 25 offset (page_number-1)*25)x),'[]'),'total',(select count(*) from public.materias where sid is null or fornecedor_id=sid));end;$$;
create function public.relatorio_editorial(sid uuid,date_from date,date_to date,page_number int default 1) returns jsonb language sql stable set search_path='' as $$select private.editorial_report(sid,date_from,date_to,page_number)$$;
create function private.commercial_calendar(date_from date,date_to date,page_number int) returns jsonb language plpgsql stable security definer set search_path='' as $$begin
 if not private.is_commercial() then raise exception 'Acesso negado';end if;
 if date_from is null or date_to is null or date_to<date_from or date_to-date_from>366 or page_number not between 1 and 10000 then raise exception 'Período inválido';end if;
 return jsonb_build_object('items',coalesce((select jsonb_agg(x) from(select c.id,c.anunciante_nome,c.produto,c.inicio,c.fim,c.status,c.pago,c.valor_centavos faturamento_centavos,coalesce((select jsonb_agg(jsonb_build_object('inicio',b.inicio,'fim',b.fim,'tipo','banner')) from public.banners b where b.contrato_id=c.id),'[]')||coalesce((select jsonb_agg(jsonb_build_object('inicio',d.inicio,'fim',d.fim,'tipo','destaque')) from public.destaques d where d.contrato_id=c.id),'[]') exibicoes from public.contratos c where c.inicio<date_to+1 and c.fim>date_from order by c.inicio,c.id limit 25 offset (page_number-1)*25)x),'[]'),'total',(select count(*) from public.contratos where inicio<date_to+1 and fim>date_from),'faturamento_centavos',(select coalesce(sum(valor_centavos),0) from public.contratos where inicio<date_to+1 and fim>date_from and status<>'cancelado'),'recebido_centavos',(select coalesce(sum(valor_centavos),0) from public.contratos where inicio<date_to+1 and fim>date_from and pago and status<>'cancelado'));end;$$;
create function public.calendario_comercial(date_from date,date_to date,page_number int default 1) returns jsonb language sql stable set search_path='' as $$select private.commercial_calendar(date_from,date_to,page_number)$$;
revoke all on function private.editorial_report(uuid,date,date,int),public.relatorio_editorial(uuid,date,date,int),private.commercial_calendar(date,date,int),public.calendario_comercial(date,date,int) from public;
grant execute on function private.editorial_report(uuid,date,date,int),public.relatorio_editorial(uuid,date,date,int),private.commercial_calendar(date,date,int),public.calendario_comercial(date,date,int) to authenticated;
